-- WFA update: the Early programs page. Insight days, fellowships, and other programs for freshmen and sophomores, with a
-- status officers keep current. Anyone can read them. The list below only goes in if the table is empty.
-- Run once in Supabase -> SQL Editor. Safe to run again.

create table if not exists public.early_programs (
  id uuid primary key default gen_random_uuid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  firm text not null check (char_length(firm) between 1 and 120),
  program text not null check (char_length(program) between 1 and 200),
  class_year text not null check (class_year in ('F', 'S', 'B')),   -- freshman, sophomore, both
  track text not null default '',
  who text not null default '',
  deadline_text text not null default '',   -- often an estimate, so it's words and not a date
  runs text not null default '',
  status text not null default 'exp' check (status in ('open', 'soon', 'exp', 'closed')),
  url text not null check (url ~* '^https?://'),
  source text not null default 'firm' check (source in ('firm', 'guide')),
  notes text not null default ''
);
alter table public.early_programs enable row level security;
drop policy if exists "anyone reads early programs" on public.early_programs;
create policy "anyone reads early programs" on public.early_programs for select using (true);
drop policy if exists "officers write early programs" on public.early_programs;
create policy "officers write early programs" on public.early_programs for all using (public.is_officer()) with check (public.is_officer());
grant select on public.early_programs to anon, authenticated;
grant insert, update, delete on public.early_programs to authenticated;
grant select, insert, update, delete on public.early_programs to service_role;

